    for qi in range(Q):
        R = int(data[idx])
        X = int(data[idx + 1])
        queries[R].append((X, qi))
        idx += 2

    ans = [0] * Q
    dp = []

    for i, a in enumerate(A, 1):
        pos = bisect_left(dp, a)
        if pos == len(dp):
